source("pre.R")
con <- duck()
q <- function(s) tryCatch(DBI::dbGetQuery(con, s)[[1]], error = function(e) paste("ERR", substr(conditionMessage(e),1,90)))
x <- decimal128(c("1.25","-1.25","99.99", NA), 5, 2)
P(x + 1L); P(1L + x); P(x * 2L); P(x + TRUE); P(x + NA); P(x + NA_integer_); P(x+NA_real_)
cat(q("SELECT typeof(1.25::DECIMAL(5,2) + 1::INTEGER)"), q("SELECT typeof(1.25::DECIMAL(5,2) * 2::INTEGER)"), q("SELECT typeof(1.25::DECIMAL(5,2) + NULL)"), q("SELECT typeof(1.25::DECIMAL(5,2) + TRUE)"),"\n")
P(x + 1); P(x + 2^31); P(x + 2^63); P(x+2^64); P(x * 1e20); P(x + 1.5); P(x + Inf); P(x * c(1, 2^40, 1, 1))
cat(q("SELECT typeof(1.25::DECIMAL(5,2) + 1)"), q("SELECT typeof(1.25::DECIMAL(5,2) + 2147483648)"), q("SELECT typeof(1.25::DECIMAL(5,2) + 9223372036854775808)"), q("SELECT typeof(1.25::DECIMAL(5,2) * 100000000000000000000)"),"\n")
P(x + int64(1)); P(int64(1) + x); P(x + uint64(1)); P(x + int128(1)); P(uint128(1) * x); P(x + bit64::as.integer64(1)); P(bit64::as.integer64(1) + x)
cat(q("SELECT typeof(1.25::DECIMAL(5,2) + 1::BIGINT)"), q("SELECT typeof(1.25::DECIMAL(5,2) + 1::UBIGINT)"), q("SELECT typeof(1.25::DECIMAL(5,2) + 1::HUGEINT)"), q("SELECT typeof(1::UHUGEINT * 1.25::DECIMAL(5,2))"), q("SELECT typeof(1.25::DECIMAL(5,2) * 1::BIGINT)"),"\n")
P(x + "1"); P(x + factor("a")); P(x + list(1)); P(x + Sys.Date()); P(-x); P(+x); P(!x); P(x & TRUE); P(x | NA)
P(x / 2L); P(x %/% 1L); P(x %% 1L); P(x ^ 2L); P(2L ^ x); P(x / x); P(x / "a"); P(x %% decimal128("0.5", 2, 1))
P(x + x[1:2]); P(x + x[1:3]); P(x + x[0]); P(x + integer())
n <- decimal128(c(a="1.5", a="2.5", b="3.5"), 5, 1)
P(n + 1L); P(1L + n); P(n + c(z=1L,y=2L,x=3L)); P(-n); P(n == n); P(n * n); P(n/n); P(abs(n)); P(round(n)); P(floor(n)); P(cumsum(n)); P(sum(n)); P(n > 2)
# comparison
P(x == 1.25); P(x == c(1.25, -1.25, 99.99, 1)); P(x < 100L); P(x == "1.25"); P(x == NA); P(x != x); P(x < 1e40); P(x > -Inf); P(x < Inf); P(x == NaN)
P(decimal128("0.1", 5, 1) == 0.1); P(decimal128("0.1", 5, 1) < 0.1); P(decimal128("0.5", 5, 1) == 0.5); P(0.1 > decimal128("0.1", 5, 1)); P(decimal128("-0.1", 5, 1) < -0.1); P(decimal128("-0.1", 5, 1) > -0.1)
P(decimal128("0.1", 38, 38) == 0.1); P(decimal128(0.1, 38, 38) == 0.1); P(decimal128("0.3", 38, 37) < 0.3)
P(decimal128("1.0", 5, 1) == decimal128("1.000", 10, 3)); P(decimal128("99999999999999999999999999999999999999", 38, 0) > decimal128("0.99999999999999999999999999999999999999", 38, 38))
P(decimal128("99999999999999999999999999999999999999", 38, 0) < uint128("100000000000000000000000000000000000000")); P(uint128("100000000000000000000000000000000000000") > decimal128(NA, 38,0)); P(decimal128("-5",38,0) > int128("-170141183460469231731687303715884105727"))
P(decimal128("99999999999999999999999999999999999999", 38, 0) < 1e38); P(decimal128("99999999999999999999999999999999999999", 38, 0) == 99999999999999999999999999999999999999); P(decimal128("9007199254740993", 38, 0) == 9007199254740992);P(decimal128("9007199254740993", 38, 0) > 9007199254740992)
P(x == bit64::as.integer64(1)); P(bit64::as.integer64(1) == decimal128("1.00",5,2)); P(x == TRUE); P(x < factor("a"))
P(decimal128("2.5", 5, 1) == 5/2); P(decimal128("1e30",38,0) == 1e30); P(decimal128("1000000000000000019884624838656",38,0) == 1e30)
P(decimal128("0.3",5,1) == 0.1+0.2); P(decimal128("-0.75",5,2) == -0.75); P(decimal128("-1.75",5,2) < -1.5);P(decimal128("-1.25",5,2) < -1.5); P(decimal128("-0.25",5,2) > -0.5)
